def selfDividingNumbers(left, right):
    out = []
    for x in range(left, right + 1):
        y = x
        ok = True
        while y:
            d = y % 10
            if d == 0 or x % d:
                ok = False
                break
            y //= 10
        if ok:
            out.append(x)
    return out
